// Mobile Web-App: Mehrfinger-Zoom und Safari-Gesten unterbinden.
// Einfingriges Scrollen und die normale Bedienung bleiben erhalten.
if (typeof document !== 'undefined') {
  const blockMultiTouchZoom = (event: TouchEvent) => {
    if (event.touches.length > 1 && event.cancelable) event.preventDefault();
  };
  document.addEventListener('touchmove', blockMultiTouchZoom, {passive: false});
  for (const name of ['gesturestart', 'gesturechange'] as const) {
    document.addEventListener(name, (event: Event) => {
      if (event.cancelable) event.preventDefault();
    }, {passive: false});
  }
}

