async function loadAdminStats(){
 if(!db||!isAdmin)return;
 const [stats,users,farmsResult,exclusions,directory]=await Promise.all([db.rpc('platform_stats'),db.rpc('admin_list_users'),db.rpc('admin_list_farms'),db.rpc('admin_dashboard_exclusions'),db.rpc('admin_directory_244')]);
 const excludedUsers=new Set<string>(exclusions.error?[]:exclusions.data?.admin_user_ids??[]);
 const excludedFarms=new Set<string>(exclusions.error?[]:exclusions.data?.placeholder_farm_ids??[]);
 // Even without the optional migration, the signed-in administrator is not a regular user.
 if(user?.id)excludedUsers.add(user.id);
 const visibleUsers:AdminUser[]=(users.data??[]).filter((u:AdminUser)=>!excludedUsers.has(u.id));
 const visibleFarms:AdminFarm[]=(farmsResult.data??[]).filter((f:AdminFarm)=>!excludedFarms.has(f.id));
 if(users.error)error(users.error);else setAdminUsers(visibleUsers.map(u=>({...u,...(directory.error?{}:(directory.data?.users??[]).find((x:AdminUser)=>x.id===u.id)??{})})));
 if(farmsResult.error)error(farmsResult.error);else setAdminFarms(visibleFarms.map(f=>({...f,...(directory.error?{}:(directory.data?.farms??[]).find((x:AdminFarm)=>x.id===f.id)??{})})));
 if(directory.error)console.warn('Admin-Verzeichnis 2.4.4:',directory.error.message);
 if(stats.error)error(stats.error);else setAdminStats({...stats.data,users:users.error?stats.data.users:visibleUsers.length,farms:farmsResult.error?stats.data.farms:visibleFarms.length});
 const loc=await db.rpc('admin_list_farm_locations');
 if(loc.error)setMapNotice('Standorte konnten nicht geladen werden: '+loc.error.message);
 else{setFarmLocations((loc.data??[]).filter((f:FarmLocation)=>!excludedFarms.has(f.id)));setMapNotice('')}
 if(exclusions.error)console.info('Admin-Bereinigung benötigt SQL-Migration 2.4.2:',exclusions.error.message);
}
 async function openAdminFarm(id:string){if(!db)return;setAdminFarmDetail(id);setAdminFarmMembers([]);const {data,error:e}=await db.rpc('admin_farm_members_244',{p_farm_id:id});if(e)error(e);else setAdminFarmMembers(data??[])}
 async function locateFarms(){
  if(!isAdmin||mapBusy)return;
  setMapBusy(true);setMapNotice('Standorte werden ermittelt. Adressen werden dafür an OpenStreetMap Nominatim übertragen.');
  const points:MapPoint[]=[];let missing=0;
  try{
   for(const f of farmLocations){
    if(!f.street_address||!f.postal_code||!f.city){missing++;continue;}
    const address=[f.street_address,f.postal_code,f.city,'Deutschland'].join(', ');
    const cacheKey='calfmanager-geocode-v1:'+f.id;
    let cached:{address:string;lat:number;lon:number}|null=null;
    try{cached=JSON.parse(localStorage.getItem(cacheKey)||'null')}catch{/* kein Cache */}
    if(cached?.address===address&&Number.isFinite(cached.lat)&&Number.isFinite(cached.lon)){
      points.push({...f,lat:cached.lat,lon:cached.lon});continue;
    }
    // Maximal eine Anfrage pro Sekunde; ausschließlich nach explizitem Admin-Klick.
    const params=new URLSearchParams({q:address,format:'json',limit:'1',countrycodes:'de'});
    const response=await fetch('https://nominatim.openstreetmap.org/search?'+params.toString(),{headers:{Accept:'application/json'}});
    if(!response.ok)throw new Error('Geocodierung vorübergehend nicht verfügbar ('+response.status+').');
    const matches=await response.json() as Array<{lat:string;lon:string}>;
    const lat=Number(matches[0]?.lat),lon=Number(matches[0]?.lon);
    if(matches.length&&Number.isFinite(lat)&&Number.isFinite(lon)){
      points.push({...f,lat,lon});
      try{localStorage.setItem(cacheKey,JSON.stringify({address,lat,lon}))}catch{/* Speicher optional */}
    }else missing++;
    setMapPoints([...points]);
    await new Promise(resolve=>setTimeout(resolve,1100));
   }
   setMapPoints(points);
   setMapNotice(`${points.length} Standorte angezeigt${missing?`; ${missing} ohne gültige Position`:''}. Die ermittelten Koordinaten werden in diesem Browser zwischengespeichert.`);
  }catch(e){setMapNotice(e instanceof Error?e.message:String(e));setMapPoints(points)}
  finally{setMapBusy(false)}
 }
