async function adminDelete(u:AdminUser){
  if(!db||!isAdmin||!user||u.id===user.id||busy)return;
  setMessage('');
  const confirmationEmail=window.prompt(`BENUTZER DAUERHAFT LÖSCHEN\n\nKonto: ${u.email}\n\nDieser Vorgang kann nicht rückgängig gemacht werden. Gib zur Bestätigung die vollständige E-Mail-Adresse ein:`);
  if(confirmationEmail===null)return;
  if(confirmationEmail.trim().toLowerCase()!==u.email.toLowerCase()){
    setMessage('Löschung abgebrochen: Die eingegebene E-Mail-Adresse stimmt nicht überein.');return;
  }
  if(!window.confirm(`LETZTE SICHERHEITSABFRAGE\n\nSoll das Konto ${u.email} wirklich dauerhaft gelöscht werden?`))return;
  setBusy(true);
  try{
    const {data:sessionData,error:sessionError}=await db.auth.getSession();
    if(sessionError||!sessionData.session?.access_token)throw new Error('Bitte melde dich erneut an.');
    const {data,error:invokeError}=await db.functions.invoke('admin-delete-user',{
      body:{target_id:u.id,confirmation_email:confirmationEmail.trim()},
      headers:{Authorization:`Bearer ${sessionData.session.access_token}`}
    });
    if(invokeError){
      let detail='';
      const context=(invokeError as {context?:Response}).context;
      if(context&&typeof context.json==='function'){
        try{const body=await context.json();detail=typeof body?.message==='string'?body.message:'';}catch{/* Keine lesbare Fehlermeldung */}
      }
      throw new Error(detail||invokeError.message||'Löschen fehlgeschlagen.');
    }
    setMessage(typeof data?.message==='string'?data.message:'Benutzerkonto wurde gelöscht.');
    await loadAdminStats();
  }catch(e){error(e)}finally{setBusy(false)}
}

