 const dueFollowups=followups.filter(f=>showFuture||String(f.due_on||'')<=today);
 const dueVaccines=vaccines.filter(v=>v.next_due_on&&(showFuture||String(v.next_due_on)<=today));
 const tag=(id:unknown)=>calves.find(c=>c.id===id)?.ear_tag||'–';
